{"content": "# Edge 自启动复查脚本（重启后双击/右键用 PowerShell 运行即可）
$ErrorActionPreference = 'SilentlyContinue'

Write-Host "=== 1. Edge 自启动项（HKCU Run）===" -ForegroundColor Cyan
$run = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
$item = Get-Item $run
$edge = (Get-ItemProperty $run).PSObject.Properties.Name | Where-Object { $_ -like '*Edge*' }
if ($edge) {
    $edge | ForEach-Object { Write-Host ("  [有] {0} => {1}" -f $_, $item.GetValue($_)) -ForegroundColor Red }
    Write-Host ("  共 {0} 条（应继续为 0）" -f $edge.Count) -ForegroundColor Red
} else {
    Write-Host "  [OK] 没有任何 Edge 启动项" -ForegroundColor Green
}

Write-Host "`n=== 2. Edge 策略是否在位 ===" -ForegroundColor Cyan
foreach ($p in @('HKLM:\SOFTWARE\Policies\Microsoft\Edge', 'HKCU:\SOFTWARE\Policies\Microsoft\Edge')) {
    $v = Get-ItemProperty $p
    Write-Host ("  {0}  StartupBoostEnabled={1}  BackgroundModeEnabled={2}" -f $p, $v.StartupBoostEnabled, $v.BackgroundModeEnabled)
}

Write-Host "`n=== 3. 本次 Edge 是怎么起来的（看父进程和命令行）===" -ForegroundColor Cyan
Get-CimInstance Win32_Process -Filter "Name='msedge.exe'" |
    Where-Object { $_.CommandLine -notmatch '--type=' } |
    ForEach-Object {
        $parent = (Get-CimInstance Win32_Process -Filter "ProcessId=$($_.ParentProcessId)").Name
        Write-Host ("  PID {0} | 父进程 {1} | {2}" -f $_.ProcessId, $parent, $_.CommandLine)
    }

Write-Host "`n=== 4. Edge 自身设置状态 ===" -ForegroundColor Cyan
$ls = Get-Content "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Local State" -Raw | ConvertFrom-Json
Write-Host ("  startup_boost.enabled = {0}   background_mode.enabled = {1}" -f $ls.startup_boost.enabled, $ls.background_mode.enabled)

Write-Host "`n提示：如果第 1 项又出现条目，说明 Edge 仍在重建自启动项，请把本窗口截图发我，我换下一层手段（计划任务级拦截）。" -ForegroundColor Yellow
Write-Host "按任意键退出..."
$null = $Host.UI.RawUI.ReadKey('NoEcho,IncludeKeyDown')
", "file_path": "C:\Users\UserX\edge-autolaunch-backup-20261029\check-autolaunch.ps1"}

{"content": "$ErrorActionPreference = 'SilentlyContinue'
$log = 'C:\Users\UserX\edge-autolaunch-backup-20261029\watch-log.txt'
$run = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
$start = Get-Date
"=== 盯梢开始 $(Get-Date -Format 'HH:mm:ss') ===" | Set-Content $log -Encoding UTF8

# 先删干净
$item = Get-Item $run
(Get-ItemProperty $run).PSObject.Properties.Name | Where-Object { $_ -like '*Edge*' } | ForEach-Object {
    "删除 $_" | Add-Content $log -Encoding UTF8
    Remove-ItemProperty -Path $run -Name $_ -ErrorAction SilentlyContinue
}
"--- 已清空，开始每 10 秒检查 ---" | Add-Content $log -Encoding UTF8

for ($i = 0; $i -lt 30; $i++) {
    Start-Sleep -Seconds 10
    $now = Get-Date
    $e = (Get-ItemProperty $run).PSObject.Properties.Name | Where-Object { $_ -like '*Edge*' }
    if ($e) {
        foreach ($n in $e) {
            "[$($now.ToString('HH:mm:ss'))] ★出现 $n = $((Get-Item $run).GetValue($n))" | Add-Content $log -Encoding UTF8
            $p = Get-CimInstance Win32_Process -Filter "Name='msedge.exe'" | Where-Object { $_.CommandLine -notmatch '--type=' }
            foreach ($pp in $p) {
                "    顶层Edge PID=$($pp.ProcessId) 启动于=$($pp.CreationDate) cmd=$($pp.CommandLine)" | Add-Content $log -Encoding UTF8
            }
        }
        break
    } else {
        "[$($now.ToString('HH:mm:ss'))] 仍为空 (第 $($i+1) 次)" | Add-Content $log -Encoding UTF8
    }
}
"=== 盯梢结束 $(Get-Date -Format 'HH:mm:ss') 共 $([int]((Get-Date)-$start).TotalSeconds) 秒 ===" | Add-Content $log -Encoding UTF8
