{"command": "pwsh -NoProfile -Command "
\$ErrorActionPreference='SilentlyContinue'
function MD5of([string]\$s) {
  \$md5=[System.Security.Cryptography.MD5]::Create()
  \$b=\$md5.ComputeHash([System.Text.Encoding]::Unicode.GetBytes(\$s))
  ((\$b | ForEach-Object { \$_.ToString('X2') }) -join '')
}
function MD5a([string]\$s) {
  \$md5=[System.Security.Cryptography.MD5]::Create()
  \$b=\$md5.ComputeHash([System.Text.Encoding]::ASCII.GetBytes(\$s))
  ((\$b | ForEach-Object { \$_.ToString('X2') }) -join '')
}
\$target='69341A5B80067155BECBC4FE9C48F5B5'
\$ud=\"\$env:LOCALAPPDATA\Microsoft\Edge\User Data\"
\$cands=@(\$ud, \$ud.ToLower(), 'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe', 'C:\Program Files (x86)\Microsoft\Edge\Application', \$env:LOCALAPPDATA + '\Microsoft\Edge')
foreach (\$c in \$cands) {
  \$u=MD5of \$c; \$a=MD5a \$c
  \$hit = if (\$u -eq \$target -or \$a -eq \$target) {' <<< MATCH'} else {''}
  '{0}{1}  (uni){2} (asc){3}' -f \$c,\$hit,\$u,\$a
}
