{"content": "import os, sys, re

targets = [b"MicrosoftEdgeAutoLaunch", b"win-session-start", b"launch_on_login", b"--launcher=on_logon_windows"]
roots = [
    r"C:\Program Files (x86)\Microsoft\Edge\Application",
    r"C:\Program Files (x86)\Microsoft\EdgeUpdate",
]

hits = {}
for root in roots:
    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            if not fn.lower().endswith((".exe", ".dll", ".crx", ".pak", ".bin")):
                continue
            p = os.path.join(dirpath, fn)
            try:
                if os.path.getsize(p) > 250 * 1024 * 1024:
                    continue
                with open(p, "rb") as f:
                    data = f.read()
            except Exception:
                continue
