New-Item -ItemType Directory -Path $t -Force | Out-Null
$err = Join-Path $t 'stderr.txt'

"=== CDP 读取 edge://policy $(Get-Date -Format 'HH:mm:ss') ===" | Set-Content $log -Encoding UTF8

$p = Start-Process 'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe' `
