                    '--remote-debugging-port=9444', 'about:blank') `
    -PassThru -NoNewWindow -RedirectStandardError $err -RedirectStandardOutput (Join-Path $t 'out.txt')

Start-Sleep -Seconds 8

try {
    Add-Type -AssemblyName System.Net.WebSockets
    $targets = Invoke-RestMethod 'http://127.0.0.1:9444/json/list' -TimeoutSec 8
    $page = $targets | Where-Object { $_.type -eq 'page' } | Select-Object -First 1
    "目标页: $($page.url)" | Add-Content $log -Encoding UTF8
    $ws = $page.webSocketDebuggerUrl

    $client = [System.Net.WebSockets.ClientWebSocket]::new()
    $client.ConnectAsync([uri]$ws, [Threading.CancellationToken]::None).Wait(8000) | Out-Null
    "WebSocket 已连接" | Add-Content $log -Encoding UTF8

    function Send-CDP($client, $json) {
        $b = [Text.Encoding]::UTF8.GetBytes($json)
        $client.SendAsync([ArraySegment[byte]]::new($b), [Net.WebSockets.WebSocketMessageType]::Text, $true, [Threading.CancellationToken]::None).Wait(8000) | Out-Null
    }
    function Recv-UntilId($client, $wantId) {
        $buf = New-Object byte[] 4194304
        for ($i = 0; $i -lt 60; $i++) {
            $sb = New-Object System.Text.StringBuilder
            do {
                $seg = [ArraySegment[byte]]::new($buf)
                $task = $client.ReceiveAsync($seg, [Threading.CancellationToken]::None)
                if (-not $task.Wait(12000)) { return $null }
                $sb.Append([Text.Encoding]::UTF8.GetString($buf, 0, $task.Result.Count)) | Out-Null
            } while (-not $task.Result.EndOfMessage)
            $txt = $sb.ToString()
            try {
                $o = $txt | ConvertFrom-Json
                if ($o.id -eq $wantId) { return $o }
            } catch { }
        }
        return $null
    }

    Send-CDP $client '{"id":1,"method":"Page.navigate","params":{"url":"edge://policy"}}'
    Recv-UntilId $client 1 | Out-Null
    Start-Sleep -Seconds 8

    Send-CDP $client '{"id":2,"method":"Runtime.evaluate","params":{"expression":"document.body.innerText","returnByValue":true}}'
    $r = Recv-UntilId $client 2
    if ($r -and $r.result.result.value) {
        $val = $r.result.result.value
        "策略页文本长度: $($val.Length)" | Add-Content $log -Encoding UTF8
        "`n===== 全文 =====" | Add-Content $log -Encoding UTF8
        $val | Add-Content $log -Encoding UTF8
    } else {
        "未取到文本" | Add-Content $log -Encoding UTF8
    }

    $client.Dispose()
} catch {
